function isPrime(num) {
  // 1 is not a prime number
  if (num === 1) {
    return false;
  }
  // 2 and 3 are prime numbers
  if (num === 2 || num === 3) {
    return true;
  }
  // Even numbers other than 2 are not prime
  if (num % 2 === 0) {
    return false;
  }
  // Check if the number is divisible by any integer between 3 and the square root of the number
  for (let I = 3; I <= Math.sqrt(num); i += 2) {
    if (num % I === 0) {
      return false;
    }
  }
  // If the number passed all the checks, it's prime
  return true;
}

